param([string]$Helper, [string]$Root)
$ErrorActionPreference = 'Stop'
. $Helper
$cases = [Console]::In.ReadToEnd() | ConvertFrom-Json -AsHashtable
$observations = [Collections.Generic.List[object]]::new()
foreach ($case in $cases) {
    $path = if ($case.name -eq 'blank') { '  ' } else { Join-Path $Root ($case.name + '.log') }
    if ($case.kind -eq 'file') { [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($case.bytes)) }
    if ($case.kind -eq 'directory') { [void][IO.Directory]::CreateDirectory($path) }
    $observations.Add(@{ name=$case.name; value=(Get-NativeReportSummary -LogPath $path) })
}
@{catastrophic=@(Get-CatastrophicPatterns); environment=@(Get-EnvironmentWarningPatterns); observations=$observations.ToArray()} | ConvertTo-Json -Depth 12 -Compress
